SELECT lower(actor_login) AS actor, toStartOfMonth(created_at, 'UTC') AS month,
  if(owner IN ('airbytehq', 'hashicorp', 'posthog', 'supabase', 'vercel'), owner, '_ext') AS owner_bucket,
  countIf(event_type = 'PullRequestEvent' AND action = 'opened') AS pr_opened,
  countIf(event_type = 'IssuesEvent' AND action = 'opened') AS issues_opened,
  countIf(event_type = 'PushEvent') AS pushes
FROM (SELECT actor_login, created_at, event_type, action, lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')) AS owner
      FROM github_events
      WHERE event_type IN ('PushEvent', 'PullRequestEvent', 'IssuesEvent')
        AND lower(actor_login) IN ('0xtbt', '1st1', '20sr20', '31carlton7', '3mdistal', '4l3k51', '7ttp', '99', 'a-440hz', 'a-anurag27', 'a-honcharenko', 'a-lider', 'aaabdelgany', 'aahel', 'aalexandrov', 'aantti', 'aaorris', 'aareet', 'aaron-lane', 'aaronbrown-vercel', 'aaronbyrne1', 'aaronsteers', 'aaronvanderlip', 'aastha-mittal', 'aayush-kapoor', 'aayushsingh2502', 'abbasrsyed', 'abbyck', 'abc3', 'abennett', 'abheek9', 'abhijeetviswa', 'abhimgowda', 'abhischekt', 'abhishek-hashicorp', 'abigailbramble', 'abishya', 'ablaszkiewicz', 'abrooks', 'absolutelightning', 'abuchanan-airbyte', 'abuxton', 'acahn', 'acdlite', 'acespacecase', 'achooo', 'achuchulev', 'acidprime', 'ack', 'aclaygray', 'acornies', 'acpana', 'acupofjose', 'adambouhmad', 'adamcavaliere', 'adamleithp', 'adams-sarah', 'adboio', 'adilyse', 'aditilonhari', 'aditshah-ibm', 'aditya2548', 'adletsmykov', 'adori30', 'adorism', 'adrianbw', 'adriancooney', 'adriandlam', 'adrianlop', 'aeschright', 'agadzik', 'agarctfi', 'ah100101', 'ahmedyamaar', 'aicarmic', 'aidan-mundy', 'aimeeu', 'airbyte-jenny', 'airbyteio', 'ajayreshc', 'ajmera-naman', 'ajmhatch', 'akashkulk', 'aklkv', 'akosuadenell', 'akshya96', 'alafanechere', 'alaister', 'alamottemitchell', 'alangenfeld', 'alanszlosek', 'aldogonzalez8', 'aldosch', 'alex-gron', 'alex-grover', 'alex-ju', 'alex-vercel', 'alexandarp', 'alexander-marquardt', 'alexanderbez', 'alexandertsukanov', 'alexandr-shegeda', 'alexandrafreeman', 'alexbasista', 'alexcarpenter', 'alexhall', 'alexisintech', 'alexkim205', 'alexkirsz', 'alexmunda', 'alexsomesan', 'ali-vercel', 'alice-wondered', 'aliciaclark1066', 'alisdair', 'allenzhou101', 'allexik', 'allisonlarson', 'allthingsclowd', 'almonk', 'alovew', 'alvin-huang', 'alzuri', 'amaliaroye', 'amandakalk', 'amanoske', 'amarrone-hashicorp', 'amays-phog', 'ambirdsall', 'amcbarnett', 'amhashicorp', 'amier3', 'amitha1005', 'amitsk6', 'amokan', 'amrithnath', 'amruta-ranade', 'amy-hashi', 'amyegan', 'amyrlam', 'ana1337x', 'analogue', 'anamahalo', 